pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // Bound each v[i] to avoid overflow in multiplication (though the reference only reverts)
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1000000000000000000);
        }
        address initialCaddress = c.caddress();
        // Call as the required from address
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address[],uint256[])", _tos, v));
        // Even if the call reverts, the state variable should not change
        assertTrue(c.caddress() == initialCaddress);
    }
}

