pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant AUTHORIZED_SENDER = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
    address constant HARDCODED_FROM = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;

    function setUp() public { 
        c = new C(); 
        vm.deal(address(this), 1 ether);
    }

    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Bound inputs: ensure _tos and v are non-empty and of same length
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // Bound v to avoid overflow in v[i] * 1e18 (use uint128 for safety)
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint128).max / 1e18);
        }

        // Record the original value of 'from' before transfer
        address originalFrom = c.from();

        // Execute transfer as the authorized sender
        vm.prank(AUTHORIZED_SENDER);
        c.transfer(_tos, v);

        // Assert that the state variable 'from' is unchanged (i.e., still equals the hardcoded address)
        assertTrue(c.from() == originalFrom && originalFrom == HARDCODED_FROM, "from should remain unchanged after transfer");
    }
}

